def proof_order_refusal(plan: Mapping[str, Any], exists: Callable[[str], bool]) -> str:
    """Why a step plan has a step whose Proof cannot pass when that step's implement reports done, or "" (SDLC gates D6,
    docs/shiploop-sdlc-gates-proposal-2026-10-30.md §5 SG1; replay evidence docs/experiments/question-record-20261031).

    A step's Proof runs at its implement's done, before that step's test stage writes its tests, and implement writes no
    tests.  ``exists(path)`` answers for the item base.  Rule A: a Proof that names a test-class path the base lacks
    cannot pass unless an earlier step declares that path in its ``paths`` (that step's test stage has written it by
    then), or the whole item is tests.  Rule B: a Proof that names a path the base lacks which only a later step declares
    needs that later step.  Paths are read from the Proof by ``command_paths``.  In the saved runs of 2026-10-03 to 10-31,
    9 of the 12 implement send-backs were this fault (8 on Codex Terra xhigh, 1 on DeepSeek flash).

    Rule A also reads the test-class paths inside a Proof's inline code (``inline_code_paths``; step-plan round 2,
    docs/experiments/step-plan-round2-20261101): replayed on 363 saved plans (352 at the commit each was accepted on,
    11 at their item's last lint tree), it flagged 2 steps, both a Proof that needed an unwritten test (one sent back, one in a run sent back for that Proof),
    and no Proof that passed implement.  Rule B is not extended to inline code: no replay supports it.

    Rule C: a Proof that is a generic suite command (``generic_command``, such as ``npm test``) cannot confirm an
    executed criterion of its step whose Confirm by (``confirm_by_command``) names a test-class path the base lacks and no
    earlier step declares.  Rule A's exemptions hold.  The step-plan duty says the Proof proves the step's criteria at its
    done.  A suite of the tests the base already has proves nothing about such a criterion: implement sends the plan back,
    or passes without proving it.  Replay evidence is in docs/experiments/proof-coverage-replay-20261101: rule C refused
    3 of 365 judged plans (2 later sent back, 1 passed unproven) and no plan whose Proof tests the step directly.
    """
    item_paths = [str(path) for path in plan.get("paths") or ()]
    if item_paths and all(classify(path) == "test" for path in item_paths):
        return ""
    steps = [step for step in plan.get("steps") or () if isinstance(step, Mapping)]
    ids = [str(step.get("id")) for step in steps]
    declared: Dict[str, List[str]] = {}
    for step in steps:
        for path in step.get("paths") or ():
            declared.setdefault(str(path), []).append(str(step.get("id")))
    criteria = {str(row.get("id")): row for row in plan.get("criteria") or () if isinstance(row, Mapping)}
    for index, step in enumerate(steps):
        proof = step.get("proof")
        if not isinstance(proof, str):
            continue
        name, earlier, later = ids[index], set(ids[:index]), set(ids[index + 1:])
        for path in command_paths(proof):
            if exists(path):
                continue
            owners = declared.get(path, [])
            if classify(path) == "test" and not earlier.intersection(owners):
                return _unwritten_test_refusal(name, path)
            if later.intersection(owners) and name not in owners and not earlier.intersection(owners):
                return ("step " + name + "'s Proof reads " + path + ", which the item base does not have and only a "
                        "later step (" + ", ".join(owner for owner in owners if owner in later) + ") declares: the "
                        "Proof needs that later step's work. Move that work into " + name + " or an earlier step, or "
                        "prove " + name + " without it, then run the same callback again.")
        for path in inline_code_paths(proof):
            if not exists(path) and classify(path) == "test" and not earlier.intersection(declared.get(path, [])):
                return _unwritten_test_refusal(name, path)
        if not generic_command(proof):
            continue
        for ident in step.get("criteria") or ():
            row = criteria.get(str(ident)) or {}
            if row.get("confirm") != "executed":
                continue
            for path in command_paths(confirm_by_command(row.get("text"))):
                if exists(path) or classify(path) != "test" or earlier.intersection(declared.get(path, [])):
                    continue
                return ("step " + name + "'s Proof `" + proof + "` runs only the tests the item base has, but "
                        + str(ident) + " is confirmed by " + path + ", which the item base does not have and no earlier "
                        "step declares: implement writes no tests, so this Proof cannot confirm " + str(ident) + " when "
                        + name + "'s implement reports done. Prove " + name + " with a command that runs its behaviour "
                        "directly (a short script with assertions, an existing test or a recorded command), keep " + path
                        + " in the focused command for the test stage, then run the same callback again.")
    return ""

#!/usr/bin/env python3
"""a0p_table.py: the A0p control (README A11 and A12) against its registered predictions P54 to P63 (journal E14).

Reads the trials' score.json (from the trial folders you name, or evidence/ once exported) and the E12 and E13 baselines in evidence/.
Prints the cells and scores each prediction as written; nothing is rescored.

  python3 a0p_table.py [TRIAL_DIR]      TRIAL_DIR holds e14-<host>-s30-a0p and e14-<host>-w5-a0p (default: evidence/)
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
EVID = HERE / "evidence"
HOSTS = ("claude", "grok", "codex")


def cell(path: Path):
    f = path / "score.json"
    if not f.is_file():
        return None
    m = json.loads(f.read_text())
    t, k = m.get("timings", {}), m.get("tokens", {})
    return {"whole": t.get("launch_to_exit_s"), "valid": m.get("valid"), "peak": m.get("peak_concurrency"), "in_all": k.get("input_all"),
            "cost": k.get("cost_usd"), "answers": (m.get("answers") or {}).get("all_correct"), "oracle": ((m.get("write") or {}).get("oracle") or {}).get("valid")}


def main(argv=None) -> int:
    trials = Path((argv or sys.argv[1:] or [str(EVID)])[0])
    rows = {}
    for host in HOSTS:
        rows[("s30", host)] = {"A0": cell(EVID / f"e12-{host}-s30-a0"), "A3": cell(EVID / f"e12-{host}-s30-a3"), "A0p": cell(trials / f"e14-{host}-s30-a0p")}
        rows[("w5", host)] = {"A0": cell(EVID / f"e13-{host}-w5-a0s"), "A3": cell(EVID / f"e13-{host}-w5-a3s"), "A0p": cell(trials / f"e14-{host}-w5-a0p")}
    for fixture, title in (("s30", "analysis5, S = 30 (A11)"), ("w5", "write5, S = 30 (A12)")):
        print(f"\n{title}: whole run (s), A0p against the same host's A0 and A3, input tokens over all contexts, cost")
        print("host    A0       A3       A0p      A0p/A0   A0p/A3   valid  peak  in A0p      in A3       in A0p/A3  cost A0p")
        for host in HOSTS:
            r = rows[(fixture, host)]
            a0, a3, p = r["A0"], r["A3"], r["A0p"]
            if not (a0 and a3):
                continue
            if not p:
                print(f"{host:<7}{a0['whole']:<9.1f}{a3['whole']:<9.1f}(no trial yet)")
                continue
            ok = p["valid"] if fixture == "s30" else (p["valid"] and p["oracle"])
            print(f"{host:<7}{a0['whole']:<9.1f}{a3['whole']:<9.1f}{p['whole']:<9.1f}{p['whole'] / a0['whole']:<9.2f}{p['whole'] / a3['whole']:<9.2f}{str(ok):<7}{p['peak']!s:<6}"
                  f"{p['in_all'] or 0:<12,}{a3['in_all'] or 0:<12,}{(p['in_all'] or 0) / (a3['in_all'] or 1):<11.2f}{p['cost'] if p['cost'] is not None else '-'}")
    print("\nPredictions as registered:")
    s30 = {h: rows[("s30", h)] for h in HOSTS}
    w5 = {h: rows[("w5", h)] for h in HOSTS}
    have = lambda rs, h: rs[h]["A0p"] and rs[h]["A0"] and rs[h]["A3"]
    if all(have(s30, h) for h in HOSTS):
        print("  P54 every analysis5 A0p valid:", all(s30[h]["A0p"]["valid"] for h in HOSTS), {h: s30[h]["A0p"]["valid"] for h in HOSTS})
        print("  P55 A0p at least 35% below A0:", all(s30[h]["A0p"]["whole"] <= 0.65 * s30[h]["A0"]["whole"] for h in HOSTS),
              {h: round(1 - s30[h]["A0p"]["whole"] / s30[h]["A0"]["whole"], 3) for h in HOSTS})
        near = {h: abs(s30[h]["A0p"]["whole"] / s30[h]["A3"]["whole"] - 1) <= 0.15 for h in HOSTS}
        print("  P56 A0p within 15% of A3 on at least two hosts:", sum(near.values()) >= 2, {h: round(s30[h]["A0p"]["whole"] / s30[h]["A3"]["whole"], 3) for h in HOSTS})
        print("  P57 A0p input tokens below A3's on every host:", all(s30[h]["A0p"]["in_all"] < s30[h]["A3"]["in_all"] for h in HOSTS))
        print("  P58 A0p not longer than A3 on Claude and Grok:", all(s30[h]["A0p"]["whole"] <= s30[h]["A3"]["whole"] for h in ("claude", "grok")))
    else:
        print("  P54 to P58: waiting for", [h for h in HOSTS if not have(s30, h)])
    if all(have(w5, h) for h in HOSTS):
        band = {"claude": (106, 144), "grok": (136, 184), "codex": (177, 240)}
        print("  P59 every write5 A0p valid:", all(w5[h]["A0p"]["valid"] and w5[h]["A0p"]["oracle"] for h in HOSTS))
        print("  P60 within 15% of A0 minus three settles:", all(band[h][0] <= w5[h]["A0p"]["whole"] <= band[h][1] for h in HOSTS), {h: round(w5[h]["A0p"]["whole"], 1) for h in HOSTS})
        print("  P61 Grok and Codex: A0p shorter than A3 shared:", all(w5[h]["A0p"]["whole"] < w5[h]["A3"]["whole"] for h in ("grok", "codex")))
        print("  P62 Claude: A0p longer than A3 shared:", w5["claude"]["A0p"]["whole"] > w5["claude"]["A3"]["whole"])
        print("  P63 A0p input tokens below A3 shared's on every host:", all(w5[h]["A0p"]["in_all"] < w5[h]["A3"]["in_all"] for h in HOSTS))
    else:
        print("  P59 to P63: waiting for", [h for h in HOSTS if not have(w5, h)])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

def _improve_focus(state: Mapping[str, Any], child: Mapping[str, Any]) -> tuple[list[str], list[str]]:
    """(the review focus, the Code craft rubric) for the reviewed stage; the rubric is [] where the focus has none."""
    stage = child["stage"]
    # The focus is numbered F1..Fn when FOCUS_IDS is on (U19); the Code craft rubric has no bullets, so the ids are the same
    # as ``focus_ids``, which counts the whole focus text.
    if stage in guidance.PLANNING_REVIEW_STAGES:
        return _numbered_focus(guidance.PLANNING_REVIEW_FOCUS.rstrip(), state, child), []
    if stage == "carry-forward":
        return _numbered_focus(guidance.END_REVIEW_FOCUS_HEAD.rstrip(), state, child), [guidance.CODE_CRAFT.rstrip()]
    if stage in stage_spec.with_improve("item"):
        return (_numbered_focus(guidance.IMPLEMENT_STEP_REVIEW_FOCUS_HEAD.rstrip(), state, child),
                [guidance.CODE_CRAFT.rstrip()])
    return [], []

def _requires_user_correction(prior: Mapping[str, Any], current: Mapping[str, Any]) -> bool:
    # Candidate changes describe a new artifact under the same requested
    # delivery outcome.  They can demand replanning, but are not themselves a
    # user scope reduction.  All other delivery requirement changes are.
    for key in ("consumer", "target", "behavior", "operation", "necessity", "exclusions", "authority"):
        if prior[key] != current[key]:
            return True
    previous = {row["id"]: row for row in _required_rows(prior)}
    replacement = {row["id"]: row for row in _required_rows(current)}
    for identifier, row in previous.items():
        replacement_row = replacement.get(identifier)
        if replacement_row is None or not _same_obligation(row, replacement_row):
            return True
    # Adding a new required check preserves (and can strengthen) the prior
    # outcome; it does not require the user to re-approve the existing scope.
    return False

def _pending(projection: Mapping[str, Any], *, phase: str | None = None) -> list[dict[str, Any]]:
    contract = projection.get("contract")
    if not isinstance(contract, Mapping):
        return []
    observations = projection["observations"]
    def satisfied(row: Mapping[str, Any]) -> bool:
        """True when the observation for ``row`` passed, or was already current for an effect or identity row."""
        status = observations.get(row["id"], {}).get("status")
        return status == "passed" or (
            status == "already-current" and row["kind"] in {"effect", "identity"}
        )

    return [
        row for row in _required_rows(contract, phase=phase) if not satisfied(row)
    ]


def _late_unrepairable_rows(
    state: Mapping[str, Any], projection: Mapping[str, Any]
) -> list[dict[str, Any]]:
    """Return required rows whose only positive verification phase has passed."""
    earlier_kinds = _EARLIER_DUE_KINDS.get(state.get("stage"), frozenset())
    return [row for row in _pending(projection) if row["kind"] in earlier_kinds]


def _require_settled(contract: Mapping[str, Any]) -> None:
    """Refuse a contract whose necessity is unresolved, or required with its authority not approved (``_unsettled``)."""
    _need(contract["necessity"] != "unresolved",
          "delivery necessity is unresolved; submit blocked with the needed decision")
    if contract["necessity"] == "required":
        _need(contract["authority"]["status"] == "approved",
              "delivery authority is unresolved; submit blocked with the needed approval")


def _require_release_ready(projection: Mapping[str, Any]) -> None:
    contract = projection.get("contract")
    _need(isinstance(contract, Mapping), "delivery contract is required before release planning")
    _require_settled(contract)
    _need(not _pending(projection, phase="system-test"),
          "required pre-update obligations are not current")


def validate_settled(state: Mapping[str, Any], action_id: str, stage: str, result: Mapping[str, Any]) -> None:
    """release-plan's done, at its own complete: refuse a result that leaves the contract unsettled (``_require_settled``).

    release-plan is an Improve checkpoint, so ``validate_transition`` runs only when its Improve review is imported; the
    necessity and authority are the stage's decision, not the review's, so they are refused here, before a review of a
    result that cannot be accepted (and ``shiploop check`` reports them).  Pre-update observations stay at the
    import: the review may refresh them.  No-op for a run without the delivery guard and for any other stage or outcome.
    """
    if (stage != "release-plan" or not isinstance(result, Mapping) or result.get("outcome") != "done"
            or state.get("delivery_contract_version") != DELIVERY_CONTRACT_VERSION):
        return
    contract = _project_submission(state, action_id, stage, result).get("contract")
    if isinstance(contract, Mapping):
        _require_settled(contract)


# The stages whose done ``validate_transition`` refuses on the contract's necessity and authority
# (``_require_release_ready``): their packets print the delivery lines in the head, where the gate's input is.
RELEASE_GATED_STAGES = frozenset(("release-plan", "release-check", "release", "release-verify", "operations", "handoff"))


def validate_transition(
    state: Mapping[str, Any], action_id: str, stage: str, result: Mapping[str, Any]
) -> dict[str, Any]:
    """Reject declared false completion without mutating navigator state."""
    projection = _project_submission(state, action_id, stage, result)
    if result["outcome"] != "done":
        return projection
    if stage == "plan":
        _need(projection["contract"] is not None,
              "delivery contract is required before successful plan")
        _need(projection["replan_required"] is None, projection["replan_required"])
    elif stage == "system-test":
        _need(not _pending(projection, phase="system-test"),
              "required pre-update obligations are not current")
    elif stage in RELEASE_GATED_STAGES:
        if stage != "release-plan":
            _need(projection["replan_required"] is None, projection["replan_required"])
        _require_release_ready(projection)
        if stage == "release":
            _need(not _pending(projection, phase="release"),
                  "required release obligations need effect and identity observations")
        elif stage == "release-verify":
            _need(not _pending(projection, phase="release"),
                  "required release obligations need current effect and identity observations")
            _need(not _pending(projection, phase="release-verify"),
                  "required release-verify behavior obligations are not current")
        elif stage in {"operations", "handoff"}:
            _need(not _pending(projection),
                  "required consumer-delivery obligations remain unfinished")

def _frozen_case_refusal(state: Mapping[str, Any], workitem: Any, result: Mapping[str, Any]) -> str | None:
    """Why a done test spec after a fix-forward amendment changes a done step's case (design rule 4), or None."""
    _action, plan = test_loop._step_plan(state, workitem)
    done = planning_revision.done_rows(plan)
    sent = _sent_back_results(state, "test-spec", workitem) if done else None
    if sent is None or sent.spec_before is None:
        return None
    steps = plan.get("steps") or []
    done_ids = {str(row.get("id")) for row in steps[:done]}

    def at_done_step(criterion: Any) -> bool:
        return iteration.case_step(str(criterion), steps) in done_ids

    supplied = result.get("test_cases")
    try:
        # An omitted list (legal when no focused command lists an ID) keeps no case, so it is compared as empty.
        cases = ({} if supplied is None else
                 {row["id"]: row for row in expectations.normalise_test_cases(supplied)})
    except expectations.ExpectationError:
        return None                       # the shape gate refuses a malformed list with its own reason
    frozen = [case for case in state["accepted"][sent.spec_before].get("test_cases") or ()
              if isinstance(case, Mapping) and at_done_step(case.get("criterion"))]
    for case in frozen:
        if cases.get(case.get("id")) != case:
            return ("test case " + str(case.get("id")) + " is due at a done step (criterion " + str(case.get("criterion"))
                    + ") and stays exactly as accepted: " + json.dumps(case, ensure_ascii=False)
                    + ". A new or changed check of that behaviour is a new case, with a new criterion, for a step still "
                    "to run")
    known = {case.get("id") for case in frozen}
    for ident, case in cases.items():
        if ident not in known and at_done_step(case.get("criterion")):
            return ("test case " + ident + "'s criterion " + str(case.get("criterion")) + " is due at a done step, so "
                    "nothing would run it as new: give it a new criterion that a step still to run lists")
    return None

if stage in unverified.STAGES:
    latest = unverified.current_list(state)[2]
