def _review_pass_archives(child: Mapping[str, Any]) -> dict[str, str]:
    """Archive every review pass's prose and pass record, not only the trivial streak the receipt lists (2026-11-04).

    The receipt names the review files the loop ended on, and a converging review ends on the pass that found
    nothing: of 601 multi-pass children in the saved corpus, 447 (74%) did their editing at an earlier pass
    (test/shiploop_e2e/LEARNINGS.md).  ``passes.md`` records that those passes edited but not what they found, and the
    worktree that holds ``review-<n>.md`` is not kept, so the findings were unreadable after the run.  The pass record
    travels with its review so a later reader can still tell which pass edited, rather than reading the archived prose
    as an unrecorded pass.  These copies sit beside the receipt's own evidence, whose numbered names stay untouched.
    """
    reviews = improve_reviews_dir(child)
    if not reviews.is_dir():
        return {}
    found = sorted((int(match.group(1)), path) for path in reviews.iterdir()
                   if (match := REVIEW_FILE.fullmatch(path.name)) and path.is_file())
    writes: dict[str, str] = {}
    for number, path in found:
        prefix = "improve/" + child["action_id"] + "/reviews"
        writes[prefix + "/review-" + str(number) + ".md"] = path.read_text(encoding="utf-8", errors="replace")
        record = reviews / ("pass-" + str(number) + ".json")
        if record.is_file():
            writes[prefix + "/pass-" + str(number) + ".json"] = record.read_text(encoding="utf-8", errors="replace")
    return writes

    # The worktree is disposable and the import now archives every pass under the run (2026-11-04), so a saved run
    # whose worktree is gone still has its reviews. Prefer the worktree when it holds notes: that is the source
    # every existing figure was measured from, and a fallback must not move them.
    if not _review_folders(root):
        archived = run_dir / "improve"
        if _review_folders(archived):
            return _improve_review_records(archived, run_dir, bound_repo="repo" in state)
    return _improve_review_records(root, run_dir, bound_repo="repo" in state)
except OSError as error:
    return {**unavailable, "unmeasured": f"Improve review evidence is unavailable: {error}"}

def floor_shapes(command: str, cwd: str | None = None) -> list[str]:
    """The shapes of ``command`` that Grok 1.0.77's headless Auto-review refuses before its classifier, sorted; an empty
    list for every other command, and for one the lexer cannot read. ``cwd`` is the session's own folder."""
    try:
        commands, empty_in_quotes, bodies = lex(command)
    except (Unreadable, IndexError, StopIteration, ValueError):
        return []
    shapes, moved = set(), False
    for position, simple in enumerate(commands):
        words = _peel(simple["words"])
        program = words[0].text.rsplit("/", 1)[-1] if words and not words[0].expands else None
        if program in ("cd", "pushd"):
            target = words[1].text if len(words) > 1 else "~"
            at_home = position == 0 and cwd is not None and target.rstrip("/") == cwd.rstrip("/")
            moved = moved or not at_home
            continue
        targets = write_targets(program, words[1:]) if program in EVERY_OPERAND | DESTINATION else []
        if any(target.expands for target in targets):
            shapes.add("var-write")
        elif moved and any(not target.text.startswith("/") for target in targets):
            shapes.add("cd-relative-write")
        for operator, target in simple["redirects"]:
            if (moved and operator in WRITE_REDIRECTS and target is not None and not target.expands
                    and not target.text.startswith("/")):
                shapes.add("cd-relative-write")
    if empty_in_quotes or any(_has_empty_backtick(body) for body in bodies):
        shapes.add("backtick-in-dq")
    return sorted(shapes)

def refusal_note(host, out: Path) -> str | None:
    """REFUSAL_NOTE for a resume, when the run's last host launch (sessions.jsonl) was a host whose permission refusal
    ends the session and that session ended on one; else None. A run with no session log gets none."""
    if not getattr(host, "refusal_ends_session", False):
        return None
    starts = [row for row in (sessionlog.read(out) or []) if row.get("row") == "start"]
    if not starts:
        return None
    try:
        launched = hosts.host(starts[-1].get("host"))
    except (KeyError, SystemExit, ValueError):
        return None
    if not getattr(launched, "refusal_ends_session", False):
        return None  # a Codex session translated into Grok's shape can print the same words in a test's output
    command = refusal_at_end(out / "events.jsonl", int(starts[-1].get("events_line") or 0))
    if command is None:
        return None
    # The rewrite is appended after formatting: its ${...} is shell text, not a format field.
    return REFUSAL_NOTE.format(head=" ".join(command.split())[:REFUSAL_HEAD_CHARS]) + grok_preempt.REWRITE

def calibrated_build_matches(build: str | None, calibrated: str | None) -> bool | None:
    """Whether a Grok build string (``grok 1.0.77 (50ca579fa996)``) is the build an installed hook's rule was probed on
    (its own record's ``calibrated_on``); None when either is unknown."""
    if not build or not calibrated:
        return None
    return calibrated in build.split()

